  static Rigidbody Deck(string name,Vector3 p,Vector3 size,bool dynamic)
  {
   var g=new GameObject(name);g.transform.position=p;var plate=SportsEventAuthoring.Box("Actual full-sized physical obstacle deck",Vector3.zero,size,rubber,friction,g.transform);SportsDrivingSurfaceAuthoring.MarkHierarchy(plate.transform);foreach(int side in new[]{-1,1})SportsEventAuthoring.Box("Readable obstacle colored rim",new Vector3(side*(size.x*.5f-.15f),size.y*.5f+.08f,0),new Vector3(.3f,.08f,size.z),dynamic?coral:cyan,null,g.transform);if(!dynamic)return null;
   var body=g.AddComponent<Rigidbody>();body.mass=26000;body.isKinematic=true;body.interpolation=RigidbodyInterpolation.Interpolate;body.collisionDetectionMode=CollisionDetectionMode.ContinuousSpeculative;body.solverIterations=24;body.solverVelocityIterations=12;body.maxAngularVelocity=1;g.transform.SetParent(m.course.motionGroup,true);bodies.Add(body);dynamics.Add(true);return body;
  }
  static void Pivot(Rigidbody body,Rigidbody support,float pitch,float roll){var joint=body.gameObject.AddComponent<ConfigurableJoint>();joint.autoConfigureConnectedAnchor=false;joint.connectedBody=support;joint.connectedAnchor=Vector3.zero;joint.enableCollision=false;joint.xMotion=joint.yMotion=joint.zMotion=ConfigurableJointMotion.Locked;joint.angularXMotion=ConfigurableJointMotion.Limited;joint.angularYMotion=ConfigurableJointMotion.Locked;joint.angularZMotion=roll>0?ConfigurableJointMotion.Limited:ConfigurableJointMotion.Locked;joint.lowAngularXLimit=new SoftJointLimit{limit=-pitch};joint.highAngularXLimit=new SoftJointLimit{limit=pitch};joint.angularZLimit=new SoftJointLimit{limit=roll};var drive=new JointDrive{positionSpring=850000,positionDamper=120000,maximumForce=float.MaxValue};joint.angularXDrive=joint.angularYZDrive=drive;}
  static Rigidbody TrussSupport(Vector3 p,float height,bool articulated=false){height=Mathf.Max(height,p.y-.5f);var footing=SportsEventAuthoring.Box("Grounded truss concrete footing",new Vector3(p.x,.5f,p.z),new Vector3(10,1,8),steel,friction);var column=SportsEventAuthoring.Box("Actual obstacle structural support",new Vector3(p.x,height*.5f,p.z),new Vector3(2,height,2),steel,friction);if(!articulated)return null;var root=new GameObject("Collision-isolated structural hinge support "+p.z);root.transform.position=p;footing.transform.SetParent(root.transform,true);column.transform.SetParent(root.transform,true);var body=root.AddComponent<Rigidbody>();body.isKinematic=true;body.useGravity=false;return body;}
  static void WarpedWall()
  {
   Deck("Warped-wall acceleration runway",new Vector3(0,11.5f,591),new Vector3(32,1,42),false);var mesh=new Mesh{name="Original continuous curved 55degree warped wall"};var vertices=new List<Vector3>();var uv=new List<Vector2>();var tri=new List<int>();const int steps=40;for(int i=0;i<=steps;i++){float theta=i/(float)steps*55*Mathf.Deg2Rad;for(int side=-1;side<=1;side+=2){vertices.Add(new Vector3(side*16,12+38*(1-Mathf.Cos(theta)),610+38*Mathf.Sin(theta)));uv.Add(new Vector2(side==1?1:0,i*.12f));}}for(int i=0;i<steps;i++){int a=i*2;tri.AddRange(new[]{a,a+2,a+1,a+1,a+2,a+3});}mesh.SetVertices(vertices);mesh.SetUVs(0,uv);mesh.SetTriangles(tri,0);mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,"Assets/"+Folder+"/Meshes/Continuous warped wall.asset");var g=new GameObject("Genuine curved warped-wall collision surface");g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=cyan;var rampContact=g.AddComponent<MeshCollider>();rampContact.sharedMesh=mesh;m.course.warpedWall=rampContact;SportsDrivingSurfaceAuthoring.MarkHierarchy(g.transform);Deck("Elevated full-truck victory landing",new Vector3(0,27.7f,658.6f),new Vector3(34,1,35),false);
   var landing=GameObject.Find("Elevated full-truck victory landing").AddComponent<Rigidbody>();landing.isKinematic=true;m.course.finaleLanding=landing;
   var bell=new GameObject("Original giant flared brass victory bell");bell.transform.position=new Vector3(0,31,670);var bellMesh=BellMesh();bell.AddComponent<MeshFilter>().sharedMesh=bellMesh;bell.AddComponent<MeshRenderer>().sharedMaterial=brass;var collider=bell.AddComponent<MeshCollider>();collider.sharedMesh=bellMesh;collider.convex=true;var body=bell.AddComponent<Rigidbody>();body.mass=5000;body.isKinematic=true;body.interpolation=RigidbodyInterpolation.Interpolate;bell.transform.SetParent(m.course.motionGroup,true);bodies.Add(body);dynamics.Add(true);var hinge=bell.AddComponent<HingeJoint>();hinge.autoConfigureConnectedAnchor=false;hinge.anchor=new Vector3(0,5,0);hinge.connectedAnchor=new Vector3(0,36,670);hinge.axis=Vector3.right;hinge.useLimits=true;hinge.limits=new JointLimits{min=-25,max=25};var hit=bell.AddComponent<NinjaBell>();hit.match=m;m.course.bell=body;foreach(int side in new[]{-1,1})SportsEventAuthoring.Box("Grounded towering victory bell gantry",new Vector3(side*20,19,670),new Vector3(1.8f,38,1.8f),coral,friction);SportsEventAuthoring.Box("Victory bell overhead crossbeam",new Vector3(0,37,670),new Vector3(43,2,2),steel,friction);
  }
  static Mesh BellMesh(){var mesh=new Mesh{name="Original lathed twelve-ring giant victory bell"};var v=new List<Vector3>();var uv=new List<Vector2>();var tri=new List<int>();for(int ring=0;ring<=12;ring++){float t=ring/12f,y=-3+t*8,r=Mathf.Lerp(4.5f,1,Mathf.Pow(t,.5f));for(int i=0;i<48;i++){float a=i*Mathf.PI*2/48;v.Add(new Vector3(Mathf.Cos(a)*r,y,Mathf.Sin(a)*r));uv.Add(new Vector2(i/48f,t));}}for(int ring=0;ring<12;ring++)for(int i=0;i<48;i++){int a=ring*48+i,b=ring*48+(i+1)%48;tri.AddRange(new[]{a,b,a+48,b,b+48,a+48});}mesh.SetVertices(v);mesh.SetUVs(0,uv);mesh.SetTriangles(tri,0);mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,"Assets/"+Folder+"/Meshes/Original giant brass bell.asset");return mesh;}
  static void Stadium()
  {
   var destination=SceneManager.GetActiveScene();var source=EditorSceneManager.OpenScene(LWS.TruckHotPotato.Editor.HotPotatoAuthoring.Scene,OpenSceneMode.Additive);try{SceneManager.SetActiveScene(destination);var crowd=source.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<LWS.TruckHotPotato.HotPotatoMatch>(true)).First().crowd;m.crowd=new GameObject("Existing optimized game-show crowd reactions").AddComponent<LWS.TruckFieldGoal.FieldGoalCrowd>();m.crowd.eventSession=m;m.crowd.nearFans=Array.Empty<Animator>();m.crowd.cheer=crowd.cheer;m.crowd.boo=crowd.boo;m.crowd.response=m.crowd.gameObject.AddComponent<AudioSource>();m.crowd.response.playOnAwake=false;m.crowd.response.spatialBlend=0;var fans=new List<MeshFilter>[crowd.batches.Length];for(int j=0;j<fans.Length;j++)fans[j]=new List<MeshFilter>();for(int side=-1;side<=1;side+=2)for(int row=0;row<5;row++){SportsEventAuthoring.Box("Finished colored stadium spectator terrace",new Vector3(side*(72+row*4),4+row*2,310),new Vector3(5,2,790),row%2==0?cyan:coral);for(int seat=0;seat<135;seat++){var batch=crowd.batches[(seat+row)%crowd.batches.Length];var fan=new GameObject("Reused optimized original show spectator");fan.transform.SetPositionAndRotation(new Vector3(side*(72+row*4),5+row*2,-70+seat*5.7f),Quaternion.Euler(0,side<0?90:-90,0));var filter=fan.AddComponent<MeshFilter>();filter.sharedMesh=batch.idle;fans[(seat+row)%crowd.batches.Length].Add(filter);fan.AddComponent<MeshRenderer>().sharedMaterials=batch.materials;}}m.crowd.batches=new LWS.TruckFieldGoal.FieldGoalCrowd.Batch[crowd.batches.Length];for(int j=0;j<fans.Length;j++)m.crowd.batches[j]=new LWS.TruckFieldGoal.FieldGoalCrowd.Batch{idle=crowd.batches[j].idle,cheer=crowd.batches[j].cheer,materials=crowd.batches[j].materials,fans=fans[j].ToArray(),seats=fans[j].Select(v=>v.transform.localToWorldMatrix).ToArray()};}finally{EditorSceneManager.CloseScene(source,true);SceneManager.SetActiveScene(destination);}
   for(int i=0;i<12;i++)foreach(int side in new[]{-1,1}){var p=new Vector3(side*65,0,-40+i*65);SportsEventAuthoring.Box("Grounded stadium spotlight tower",p+Vector3.up*18,new Vector3(1,36,1),steel,friction);var lamp=new GameObject("Actual broad show floodlight").AddComponent<Light>();lamp.transform.position=p+Vector3.up*35;lamp.type=LightType.Spot;lamp.transform.rotation=Quaternion.Euler(65,side>0?-90:90,0);lamp.range=90;lamp.spotAngle=90;lamp.intensity=70;lamp.color=side>0?new Color(.3f,.85f,1):new Color(1,.42f,.25f);}
  }
  static void Artwork(){var logo=SportsRetroMenuAuthoring.LoadLogo(Folder);foreach(int i in new[]{0,4}){var page=m.menus.pages[i];var art=SportsUIAuthoring.Rect("Original sport title artwork",page.transform,new Vector2(260,160),new Vector2(-560,365)).AddComponent<UnityEngine.UI.Image>();art.sprite=logo;art.preserveAspect=true;art.raycastTarget=false;var title=page.transform.Find("Title").GetComponent<TMP_Text>();title.rectTransform.anchoredPosition+=Vector2.right*140;title.rectTransform.sizeDelta=new Vector2(1000,title.rectTransform.sizeDelta.y);}var material=SportsEventAuthoring.Mat(Folder,"Original grungy Ninja stadium artwork",Color.white);material.shader=Shader.Find("Universal Render Pipeline/Unlit");material.mainTexture=logo.texture;material.SetFloat("_Surface",1);material.SetFloat("_SrcBlend",5);material.SetFloat("_DstBlend",10);material.SetFloat("_ZWrite",0);material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");material.renderQueue=3000;foreach(float z in new[]{-75f,686}){var sign=GameObject.CreatePrimitive(PrimitiveType.Quad);sign.name="Original supported Ninja gameshow logo";Object.DestroyImmediate(sign.GetComponent<Collider>());sign.transform.position=new Vector3(0,32,z);sign.transform.localScale=new Vector3(55,34,1);sign.GetComponent<Renderer>().sharedMaterial=material;foreach(int side in new[]{-1,1})SportsEventAuthoring.Box("Grounded branded show gantry column",new Vector3(side*28,25,z+.5f),new Vector3(1,50,1),steel,friction);SportsEventAuthoring.Box("Branded show gantry crossbeam",new Vector3(0,50,z+.5f),new Vector3(57,1,1),steel,friction);}}
